import React, { useState } from 'react';
import { GraduationCap, Heart, Users, Settings, ArrowRight, Sparkles } from 'lucide-react';
import { baseStyles, FONT_DISPLAY } from '../../styles/global';

export function LoginScreen({ onLogin }) {
  const [name, setName] = useState('');
  const [role, setRole] = useState('student');
  const styles = baseStyles;

  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      padding: 24,
      background: 'linear-gradient(180deg, #FAFBFF 0%, #F5F3FF 100%)',
      position: 'relative',
    }}>
      <div style={{
        background: 'white',
        borderRadius: 24,
        boxShadow: '0 20px 60px rgba(0,0,0,0.1)',
        maxWidth: 500,
        width: '100%',
        padding: 48,
        zIndex: 10,
        position: 'relative',
      }}>
        <div style={{ textAlign: 'center', marginBottom: 32 }}>
          <div style={{
            width: 60,
            height: 60,
            borderRadius: 16,
            background: 'linear-gradient(135deg, #9B5DE5 0%, #F15BB5 100%)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            margin: '0 auto 16px',
          }}>
            <Sparkles size={32} strokeWidth={2.5} />
          </div>
          <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 36, fontWeight: 900, color: '#1F2937', margin: '0 0 8px 0' }}>
            LearnQuest
          </h1>
          <p style={{ fontSize: 14, color: '#6B7280', margin: 0 }}>Where every kid becomes a learning champion</p>
        </div>

        <div>
          <label style={{ display: 'block', fontSize: 13, fontWeight: 600, color: '#374151', marginBottom: 8 }}>
            What's your name?
          </label>
          <input
            type="text"
            value={name}
            onChange={e => setName(e.target.value)}
            placeholder="Type your first name"
            style={{
              width: '100%',
              padding: '12px 16px',
              borderRadius: 10,
              border: '2px solid #E5E7EB',
              fontSize: 14,
              fontFamily: 'inherit',
              marginBottom: 24,
            }}
            onKeyDown={e => e.key === 'Enter' && onLogin(name, role)}
          />

          <label style={{ display: 'block', fontSize: 13, fontWeight: 600, color: '#374151', marginBottom: 12 }}>
            I'm a...
          </label>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12, marginBottom: 24 }}>
            {[
              { id: 'student', label: 'Student', icon: GraduationCap, color: '#3DB2FF' },
              { id: 'parent',  label: 'Parent',  icon: Heart, color: '#F15BB5' },
              { id: 'teacher', label: 'Teacher', icon: Users, color: '#7DCE82' },
              { id: 'admin',   label: 'Admin',   icon: Settings, color: '#FFB627' },
            ].map(r => {
              const Icon = r.icon;
              const active = role === r.id;
              return (
                <button
                  key={r.id}
                  onClick={() => setRole(r.id)}
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: 8,
                    padding: 16,
                    borderRadius: 12,
                    borderWidth: 2,
                    borderStyle: 'solid',
                    borderColor: active ? r.color : '#E5E7EB',
                    background: active ? r.color : 'white',
                    color: active ? 'white' : '#374151',
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                    fontWeight: 600,
                    fontSize: 13,
                  }}
                >
                  <Icon size={20} />
                  <span>{r.label}</span>
                </button>
              );
            })}
          </div>

          <button 
            onClick={() => onLogin(name, role)} 
            style={{...styles.primaryBtn, width: '100%', justifyContent: 'center', marginBottom: 16}}
          >
            Start Learning <ArrowRight size={18} />
          </button>

          <p style={{ fontSize: 12, color: '#6B7280', textAlign: 'center', margin: 0 }}>
            Demo mode — all progress is saved for this session.
          </p>
        </div>
      </div>
    </div>
  );
}
